#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
char *recite(unsigned start, unsigned take) {
    const char *n[] = {"no",  "one",   "two",   "three", "four", "five",
                       "six", "seven", "eight", "nine",  "ten"};
    char *out = (char *)calloc(5000, 1);
    if (start > 10 || start < take)
        return out;
    for (unsigned i = start; i > start - take; i--) {
        if (i < start)
            strcat(out, "\n\n");
        char word[20];
        strcpy(word, n[i]);
        word[0] = (char)toupper((unsigned char)word[0]);
        sprintf(out + strlen(out),
                "%s green bottle%s hanging on the wall,\n%s green bottle%s hanging on "
                "the wall,\nAnd if one green bottle should accidentally "
                "fall,\nThere'll be %s green bottle%s hanging on the wall.",
                word, i == 1 ? "" : "s", word, i == 1 ? "" : "s", n[i - 1],
                i == 2 ? "" : "s");
    }
    return out;
}

